<template>
  <div class="fixed inset-0 z-[10000] flex items-center justify-center bg-white dark:bg-darktheme-card p-5">
    <form class="w-full max-w-xs flex flex-col items-center" @submit.prevent="unlock">
      <i class="fas fa-lock text-blue text-4xl mb-4" aria-hidden="true"></i>
      <h1 class="text-xl font-bold mb-1">Warpnet is locked</h1>
      <p class="text-sm text-dark mb-5 text-center">Your node keeps running. Enter your PIN to continue.</p>
      <input
        ref="pin"
        v-model="pin"
        type="password"
        inputmode="numeric"
        autocomplete="off"
        maxlength="8"
        aria-label="PIN"
        placeholder="PIN"
        class="w-full rounded border border-lighter bg-white p-2 text-center text-lg tracking-widest"
        :disabled="isBusy"
      />
      <p v-if="error" class="text-sm text-red-600 mt-2 text-center" role="alert">{{ error }}</p>
      <button
        type="submit"
        :disabled="isBusy || !pin"
        class="w-full mt-4 text-white bg-blue rounded-full font-semibold px-5 py-2 hover:bg-darkblue disabled:opacity-50"
      >
        {{ isChecking ? "Checking…" : "Unlock" }}
      </button>
      <button type="button" class="mt-4 text-sm text-dark underline flat-btn" :disabled="isBusy" @click="signOut">
        {{ isSigningOut ? "Signing out…" : "Forgot PIN? Sign out" }}
      </button>
    </form>
  </div>
</template>

<script>
import {screenLock, unlockScreen} from "@/lib/screen-lock";
import {warpnetService} from "@/service/service";

export default {
  name: "LockScreen",
  data() {
    return {
      pin: "",
      error: "",
      isChecking: false,
      isSigningOut: false,
    };
  },
  computed: {
    isBusy() {
      return this.isChecking || this.isSigningOut;
    },
  },
  methods: {
    async unlock() {
      if (this.isBusy || !this.pin) return;
      this.isChecking = true;
      this.error = "";
      const isUnlocked = await unlockScreen(this.pin);
      this.isChecking = false;
      this.pin = "";
      if (isUnlocked) return;
      if (screenLock.attemptsLeft <= 0) {
        await this.signOut();
        return;
      }
      this.error = `Wrong PIN. ${screenLock.attemptsLeft} attempt${screenLock.attemptsLeft === 1 ? "" : "s"} left before sign-out.`;
      this.$nextTick(() => this.$refs.pin?.focus());
    },
    async signOut() {
      if (this.isSigningOut) return;
      this.isSigningOut = true;
      try {
        await warpnetService.logoutUser();
      } catch (err) {
        console.error("Failed to sign out:", err);
      }
      this.isSigningOut = false;
      this.$router.push({ name: "Root" });
    },
  },
  mounted() {
    // A reload after the last wrong PIN but before sign-out finished.
    if (screenLock.attemptsLeft <= 0) {
      this.signOut();
      return;
    }
    this.$refs.pin?.focus();
  },
};
</script>
